import torch
import torch.nn as nn
from torch import Tensor, device, dtype
import sys
import time
import gc

from typing import Union, Tuple, Any, Callable, Iterator, Set, Optional, overload, TypeVar, Mapping, Dict
from collections import OrderedDict
from transformers import MM, GELUActivation

from tempo.inplace_gelu import InplaceGelu
from tempo.inplace_layernorm import InplaceLayerNorm
from tempo.combined import Combined

class AutoModule(nn.Module):
    def __init__(self, model, inp_size):
        super().__init__()
        self.model = model
        AutoModule.convert_layers(model, inp_size)

    @staticmethod
    def convert_helper(module):
        p1, p2 = (None, None), (None, None)
        for name, child in module.named_children():
            # Do not convert layers that are already quantized
            if isinstance(child, (InplaceGelu, InplaceLayerNorm, Combined)):
                continue
            if isinstance(child, (nn.GELU, GELUActivation)):
                setattr(module, name, InplaceGelu())
            elif isinstance(child, nn.LayerNorm):
                setattr(module, name, InplaceLayerNorm(child.normalized_shape))
            elif (isinstance(child, MM) and isinstance(p1[1], nn.Dropout) and isinstance(p2[1], nn.Softmax)):
                setattr(module, p1[0], nn.Identity())
                setattr(module, p2[0], nn.Identity())
                setattr(module, name, Combined(p2[1].dim, p1[1].p))
            else:
                AutoModule.convert_helper(child)
            p2 = p1
            p1 = (name, child)

    @staticmethod
    def convert_layers(module, inp_size):
        batch_size = 1
        batch_inc = 1
        times = []
        batch_sizes = []
        m = module
        m.cuda()
        while True:
            try:
                sizes = [batch_size] + list(inp_size)
                gc.collect()
                torch.cuda.empty_cache()
                inp = torch.randn(sizes, device='cuda')
                start = time.perf_counter_ns()
                out = m(inp)
                out.backward()
                end = time.perf_counter_ns()
                del out
                del inp
                times.append(end - start)
                batch_sizes.append(batch_size)
                batch_size += batch_inc
                batch_inc *= 2
            except:
                if (batch_inc == 1):
                    break
                else:
                    batch_size -= (batch_inc // 2)
                    batch_inc = 1

        print(list(zip(batch_sizes, times)))
        should_convert = False
        if (len(times) <= 2):
            should_convert = True
        else:
            r1 = (times[-1]/times[-2])
            b1 = (batch_sizes[-1]/batch_sizes[-2])
            r2 = (times[-2]/times[-3])
            b2 = (batch_sizes[-2]/batch_sizes[-3])
            c = 0.85
            if (r1 < c*b1 and r2 < c*b2):
                should_convert = True

        if should_convert:
            AutoModule.convert_helper(module)

    def forward(self, *args, **kwargs):
        return self.model(*args, **kwargs)

    def train(self, mode: bool = True):
        return super().train()

    def eval(self):
        return super().eval()

    def load_state_dict(self, state_dict: Union[Dict[str, Tensor], Dict[str, Tensor]],
                        strict: bool = True):
        # remove the prefix "model." added by this wrapper
        new_state_dict = OrderedDict([("model." + k,  v) for k, v in state_dict.items()])
        return super().load_state_dict(new_state_dict, strict)

    def state_dict(self, destination=None, prefix='', keep_vars=False):
        ret = super().state_dict(destination, prefix, keep_vars)

        # remove the prefix "model." added by this wrapper
        ret = OrderedDict([(k[6:], v) for k, v in ret.items()])
        return ret

import torch.nn as nn

class MatmulMod:
    """
    Do matrix multiplication for module.
    """
    @classmethod
    def param(cls, w, B=None, A=None, conv=False):
        # TODO Reconstruct this part
        out = w
        if B != None:
            if conv:
                out = B.matmul(out.view(out.size(0), -1))
                out = out.reshape(out.size(0), w.size(1), w.size(2), w.size(3))
            else:
                out = B.matmul(out)
        if A != None:
            # TODO: Make it more clear
            if conv:
                out = out.transpose(0, 1)
                shape = out.shape
                out = out.reshape(out.size(0), -1)
                out = (A.T.matmul(out))
                out = out.reshape(out.size(0), shape[1], shape[2], shape[3])
                out = out.transpose(0, 1)
            else:
                out = out.matmul(A)
        return out

    @classmethod
    def linear_in_place(cls, mod, B, A):
        cls.linear(mod, mod, B, A)

    @classmethod
    def linear(cls, src_mod, tgt_mod, B, A):
        tgt_mod.weight.data = cls.param(src_mod.weight.data, B, A, conv=isinstance(src_mod, nn.Conv2d))
        if hasattr(tgt_mod, "bias") and tgt_mod.bias is not None:
            tgt_mod.bias.data = cls.param(src_mod.bias.data, B, None)

    @classmethod
    def layernorm_in_place(cls, mod, B):
        cls.layernorm(mod, mod, B)

    @classmethod
    def layernorm(cls, src_mod, tgt_mod, B):
        tgt_mod.weight.data = cls.param(src_mod.weight.data, B)
        if hasattr(tgt_mod, "bias") and tgt_mod.bias is not None:
            tgt_mod.bias.data = cls.param(src_mod.bias.data, B)


class MatmulLayers:
    """
    Do depth matrix multiplication for layers
    """
    @classmethod
    def layers(cls, src_layers, tgt_layers, M):
        assert M.size(0) == len(tgt_layers)
        assert M.size(1) == len(src_layers)

        for t, tl in enumerate(tgt_layers):
            weighted_params = []
            for s, sl in enumerate(src_layers):
                param_len = len(list(sl.parameters()))
                for p, param in enumerate(list(sl.parameters())):
                    if len(weighted_params) < param_len:
                        weighted_params.append(param.data.clone() * M[t, s])
                    else:
                        weighted_params[p] += param.data.clone() * M[t, s]
            for p, param in enumerate(list(tl.parameters())):
                param.data[:] = weighted_params[p]

